import{_ as t,c as i,o as a,ag as s}from"./chunks/framework.DuVOYUUM.js";const u=JSON.parse('{"title":"Documentation Guide","description":"","frontmatter":{"prev":false,"next":false,"order":1},"headers":[],"relativePath":"guide.md","filePath":"guide.md","lastUpdated":1790647345000}'),o={name:"guide.md"};function r(l,e,n,h,d,p){return a(),i("div",null,e[0]||(e[0]=[s(`<h1 id="documentation-guide" tabindex="-1">Documentation Guide <a class="header-anchor" href="#documentation-guide" aria-label="Permalink to &quot;Documentation Guide&quot;">​</a></h1><nav class="table-of-contents"><ul><li><a href="#overview">Overview</a></li><li><a href="#how-to-write-markdown">How to Write Markdown</a></li><li><a href="#how-to-create-and-edit-pages">How to Create and Edit Pages</a><ul><li><a href="#file-and-folder-structure">File and Folder Structure</a></li><li><a href="#simple">Simple</a></li><li><a href="#intermediate">Intermediate</a></li><li><a href="#advanced">Advanced</a></li></ul></li><li><a href="#other-misc-things">Other Misc. Things</a><ul><li><a href="#changing-settings">Changing Settings</a></li><li><a href="#github-pages">GitHub Pages</a></li></ul></li></ul></nav><h2 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to &quot;Overview&quot;">​</a></h2><p>This documentation is powered by a tool called <a href="https://vitepress.dev/" target="_blank" rel="noreferrer">VitePress</a>, which allows you to create <a href="https://en.wikipedia.org/wiki/Markdown" target="_blank" rel="noreferrer">Markdown</a> files and have them published in the form of a website with proper formatting, navigation between pages, etc.</p><h2 id="how-to-write-markdown" tabindex="-1">How to Write Markdown <a class="header-anchor" href="#how-to-write-markdown" aria-label="Permalink to &quot;How to Write Markdown&quot;">​</a></h2><p>First, here are some resources to get started with Markdown&#39;s syntax:</p><ul><li>Basic: <a href="https://www.markdownguide.org/cheat-sheet/" target="_blank" rel="noreferrer">https://www.markdownguide.org/cheat-sheet/</a></li><li>Advanced: <a href="https://vitepress.dev/guide/markdown" target="_blank" rel="noreferrer">https://vitepress.dev/guide/markdown</a></li></ul><p>The idea behind Markdown is to write text files that include formatting (like bold, italic, bulleted lists, tables, etc.) while having both the source text and the final document be easy to read regardless of which format you are viewing. To create a Markdown file, open your text editor of choice, and create a file with an extension of <code>.md</code>. Some text editors, like <a href="https://code.visualstudio.com/" target="_blank" rel="noreferrer">VS Code</a> even have the ability to preview Markdown files right within the application. Alternatively, there are several in-browser Markdown editors available <a href="https://www.google.com/search?q=markdown+editor+in+browser" target="_blank" rel="noreferrer">here</a>. Markdown files are written in just like any other text file, and there is no &quot;compilation&quot; step or anything of that sort. What you see is simply what you get. <a href="https://github.com/oaklandrobotics/docs/blob/main/src/guide.md?plain=1" target="_blank" rel="noreferrer">Here&#39;s what the source for this page looks like.</a></p><p>In general, Markdown uses different symbols to format texts in different ways, like so:</p><table tabindex="0"><thead><tr><th style="text-align:center;">Formatted Text</th><th style="text-align:center;">Source Text</th></tr></thead><tbody><tr><td style="text-align:center;">This is <em>italic</em></td><td style="text-align:center;"><code>This is _italic_</code></td></tr><tr><td style="text-align:center;">This is <strong>bold</strong></td><td style="text-align:center;"><code>This is **bold**</code></td></tr><tr><td style="text-align:center;">This is <em><strong>bold and italic</strong></em></td><td style="text-align:center;"><code>This is _**bold and italic**_</code></td></tr><tr><td style="text-align:center;">This is a <a href="https://oaklandrobotics.org/" target="_blank" rel="noreferrer">link</a></td><td style="text-align:center;"><code>This is a [link](https://oaklandrobotics.org)</code></td></tr></tbody></table><ul><li>This is a bulleted list</li><li>Here&#39;s another item</li></ul><div class="language-md vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">md</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> This is a bulleted list</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> Here&#39;s another item</span></span></code></pre></div><br><ol><li>This is an ordered list</li><li>Step 2</li></ol><div class="language-md vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">md</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">1.</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> This is an ordered list</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">2.</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> Step 2</span></span></code></pre></div><h2 id="how-to-create-and-edit-pages" tabindex="-1">How to Create and Edit Pages <a class="header-anchor" href="#how-to-create-and-edit-pages" aria-label="Permalink to &quot;How to Create and Edit Pages&quot;">​</a></h2><h3 id="file-and-folder-structure" tabindex="-1">File and Folder Structure <a class="header-anchor" href="#file-and-folder-structure" aria-label="Permalink to &quot;File and Folder Structure&quot;">​</a></h3><p>The way VitePress handles how it constructs the website is determined by what folder a file resides in. A markdown file corresponds to a single page on the website, and a folder corresponds to a category on the website. For example, <code>src/projects/igvc-2024/testing.md</code> would be visible at <code>https://docs.oaklandrobotics.org/projects/igvc-2024/testing</code>. This folder structure also determines the layout of the sidebar that appears on the left when you are viewing a page. Each folder represents a &quot;drop-down&quot; (a row with the collapsing arrow) in the sidebar. In addition, each folder in the list can have its own page by creating a file called <code>index.md</code> in that folder. Finally, for all files, it will first see if a title was specified in the file itself (usually the first <code>#</code> heading). This title will be used on both the sidebar and in the name of the tab in your browser.</p><h3 id="simple" tabindex="-1">Simple <a class="header-anchor" href="#simple" aria-label="Permalink to &quot;Simple&quot;">​</a></h3><p>The simplest way to create and edit pages is to do it directly through GitHub, where the source code for all the files is stored.</p><h4 id="editing-a-file" tabindex="-1">Editing a file <a class="header-anchor" href="#editing-a-file" aria-label="Permalink to &quot;Editing a file&quot;">​</a></h4><ol><li>At the bottom of most of the pages on the website is a link that says &quot;Edit this page on GitHub.&quot; Click on it.</li><li>You will be brought to GitHub&#39;s in-browser text editor for that specific file.</li><li>Make your changes to the file.</li><li>When you are done, click on &quot;Commit changes...&quot;</li><li>In the box labeled &quot;Commit message&quot;, write a very brief message about what your changes were. <ul><li>This doesn&#39;t have to be too long, as it is a max. of 50 characters. Use the optional &quot;extended description&quot; field if you need more words.</li></ul></li><li>Click on &quot;Commit changes.&quot;</li></ol><p>That&#39;s it! Your changes should be visible on the website after GitHub rebuilds the website. This process should take ~1 minute. (Be sure to refresh the page.)</p><h4 id="creating-a-file" tabindex="-1">Creating a file <a class="header-anchor" href="#creating-a-file" aria-label="Permalink to &quot;Creating a file&quot;">​</a></h4><ol><li>Go to <a href="https://github.com/oaklandrobotics/docs" target="_blank" rel="noreferrer">the GitHub repository</a>.</li><li>Click on the <code>src</code> folder, then navigate to where you would like to create your page.</li><li>Click &quot;Add file,&quot; then &quot;Create new file&quot;</li><li>Enter a filename in the box labeled &quot;Name your file...&quot;</li><li>Write your content. Make sure to include a <code>#</code> heading so the page can have a proper title.</li><li>When you are done, click on &quot;Commit changes...&quot;</li><li>In the box labeled &quot;Commit message&quot;, write a very brief message about what your changes were. <ul><li>This doesn&#39;t have to be too long, as it is a max. of 50 characters. Use the optional &quot;extended description&quot; field if you need more words.</li></ul></li><li>Click on &quot;Commit changes.&quot;</li></ol><p>That&#39;s it! Your changes should be visible on the website after GitHub rebuilds the website. This process should take ~1 minute. (Be sure to refresh the page.)</p><h3 id="intermediate" tabindex="-1">Intermediate <a class="header-anchor" href="#intermediate" aria-label="Permalink to &quot;Intermediate&quot;">​</a></h3><p>This is convenient if you need to make multiple changes, as you don&#39;t have to commit them one at a time. You can make all your changes and push them to the repository at once.</p><ol><li>Go to <a href="https://github.com/oaklandrobotics/docs" target="_blank" rel="noreferrer">the GitHub repository</a>.</li><li>Press the period key (<code>.</code>) on your keyboard. This will open the repository in github.dev, an in-browser IDE.</li><li>On the left side of the screen, use the file picker to navigate to your desired file or folder in the <code>src</code> directory. You can right-click on a folder to create new files or folders in that folder.</li><li>Make your changes. Click the icon that looks like two rectangles and a magnifying glass to preview a file.</li><li>When you are ready to push your changes, click the &quot;Source Control&quot; button on the far left of your screen.</li><li>Enter a commit message in the &quot;Message&quot; field.</li><li>Click on &quot;Commit &amp; Push&quot;</li></ol><p>That&#39;s it! Your changes should be visible on the website after GitHub rebuilds the website. This process should take ~1 minute. (Be sure to refresh the page.)</p><h3 id="advanced" tabindex="-1">Advanced <a class="header-anchor" href="#advanced" aria-label="Permalink to &quot;Advanced&quot;">​</a></h3><p>You probably know what you&#39;re doing. (This is also how can you preview the website locally on your own computer before pushing changes)</p><ol><li><a href="https://nodejs.org/en/download" target="_blank" rel="noreferrer">Install Node.js</a></li><li>Clone the repo</li><li>Open a terminal in the same directory as the repo, and run this command: <ul><li>Take a look at this guide for more info: <a href="https://vitepress.dev/guide/getting-started" target="_blank" rel="noreferrer">https://vitepress.dev/guide/getting-started</a></li></ul></li></ol><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span></span></code></pre></div><p><strong>(Optional)</strong> If you want to update the dependencies, (i.e. VitePress, which updates fairly often), you can run</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> add</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -D</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> vitepress</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> vitepress-sidebar</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> markdown-it-mathjax3</span></span></code></pre></div><ol start="4"><li>Start up the dev server with this command.</li></ol><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> docs:dev</span></span></code></pre></div><ol start="5"><li>You should see a message similar to this. Enter the URL it gives you in your browser to see the preview of the webpage.</li></ol><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">  vitepress</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> v1.0.1</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">  ➜</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  Local:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">   http://localhost:5173/</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">  ➜</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  Network:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> use</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --host</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> to</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> expose</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">  ➜</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  press</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> h</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> to</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> show</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> help</span></span></code></pre></div><ol start="6"><li>Make your changes and push &#39;em.</li></ol><p>That&#39;s it! Your changes should be visible on the website after GitHub rebuilds the website. This process should take ~1 minute. (Be sure to refresh the page.)</p><h2 id="other-misc-things" tabindex="-1">Other Misc. Things <a class="header-anchor" href="#other-misc-things" aria-label="Permalink to &quot;Other Misc. Things&quot;">​</a></h2><h3 id="changing-settings" tabindex="-1">Changing Settings <a class="header-anchor" href="#changing-settings" aria-label="Permalink to &quot;Changing Settings&quot;">​</a></h3><p>You can change the settings and behaviors of the website by editing <a href="https://github.com/oaklandrobotics/docs/blob/main/.vitepress/config.mts" target="_blank" rel="noreferrer"><code>.vitepress/config.mts</code></a>. This includes things like the navbar at the top, the sidebar, and the theme of the website, among other things. This requires very light knowledge of how TypeScript and Vue.js work. Take a look at these guides for more info:</p><ul><li><a href="https://vitepress.dev/reference/site-config" target="_blank" rel="noreferrer">https://vitepress.dev/reference/site-config</a></li><li><a href="https://vitepress.dev/reference/default-theme-config" target="_blank" rel="noreferrer">https://vitepress.dev/reference/default-theme-config</a></li><li><a href="https://vitepress.dev/guide/frontmatter" target="_blank" rel="noreferrer">https://vitepress.dev/guide/frontmatter</a></li><li><a href="https://vitepress-sidebar.jooy2.com/api" target="_blank" rel="noreferrer">https://vitepress-sidebar.jooy2.com/api</a></li></ul><h3 id="github-pages" tabindex="-1">GitHub Pages <a class="header-anchor" href="#github-pages" aria-label="Permalink to &quot;GitHub Pages&quot;">​</a></h3><p>The website itself is hosted on GitHub Pages. In order for this to work properly VitePress needs to generate the actual <code>.html</code> pages that are hosted by GitHub Pages. This is made possible by a GitHub Action workflow that builds the webpage and deploys it with GitHub Pages. The workflow can be found at <a href="https://github.com/oaklandrobotics/docs/blob/main/.github/workflows/deploy.yml" target="_blank" rel="noreferrer"><code>.github/workflows/deploy.yml</code></a>. It will run every time the repo is pushed to on the <code>main</code> branch. If it seems like the website is not updating, make sure there is a green &quot;✅&quot; icon next to the most recent commit. If there is an &quot;❌,&quot; it means the build failed for some reason. Check the logs to troubleshoot the issue.</p><p>More info: <a href="https://vitepress.dev/guide/deploy#github-pages" target="_blank" rel="noreferrer">https://vitepress.dev/guide/deploy#github-pages</a></p>`,49)]))}const g=t(o,[["render",r]]);export{u as __pageData,g as default};
